const gymBooks=[['self-defense','Self Defense in Workplace','Defense gains +30% for 31 days','resilience',1.3],['limbo-lovers','Limbo Lovers 101','Dexterity gains +30% for 31 days','precision',1.3],['speed-3','Speed 3','Speed gains +30% for 31 days','reflexes',1.3],['gym-grunting','Gym Grunting','Strength gains +30% for 31 days','power',1.3],['get-hard','Get Hard Or Go Home','All gym gains +20% for 31 days','all',1.2],['higher-daddy','Higher Daddy Higher','Energy regeneration +20% for 31 days','regen',1.2]];
function gymById(id){return gymCatalog.find(g=>g.id===id)||gymCatalog[0]}
function inJail(){return Number(state.jailUntil)>Date.now()}
function ensureGymData(){if(!state.gym||typeof state.gym!=='object')state.gym={active:'premier',memberships:['premier'],exp:0,sessions:0,bookEffects:[],lastAction:''};if(!Array.isArray(state.gym.memberships))state.gym.memberships=['premier'];if(!state.gym.memberships.includes('premier'))state.gym.memberships.unshift('premier');if(!Number.isFinite(state.gym.exp)||state.gym.exp<0)state.gym.exp=0;if(!Number.isFinite(state.gym.sessions)||state.gym.sessions<0)state.gym.sessions=0;if(!Array.isArray(state.gym.bookEffects))state.gym.bookEffects=[];if(inJail()){if(!state.gym.memberships.includes('crims'))state.gym.memberships.push('crims');state.gym.active='crims'}else if(state.gym.active==='crims')state.gym.active='premier';return state.gym}
function gymTotals(){return gymStatKeys.reduce((sum,k)=>sum+(Number(state[k])||0),0)}
function drugTotal(){return Number(state.drugUses?.Xanax||0)+Number(state.drugUses?.Ecstasy||0)}
function gymRequirement(g){const total=gymTotals(),str=(state.power||0)+(state.reflexes||0),def=(state.resilience||0)+(state.precision||0),second=Math.max(...gymStatKeys.filter(k=>k!==({ 'gym-3000':'power','mr-isoyamas':'resilience','total-rebound':'reflexes',elites:'precision'}[g.id]||'')).map(k=>Number(state[k])||0));if(g.id==='crims')return inJail()?'Jail status active.':'Only available while jailed.';if(g.id==='balboas')return `Cha Cha’s membership and Defense + Dexterity ${Math.round(def)} must be at least 25% above Strength + Speed ${Math.round(str)}.`;if(g.id==='frontline')return `Cha Cha’s membership and Strength + Speed ${Math.round(str)} must be at least 25% above Defense + Dexterity ${Math.round(def)}.`;if(g.id==='gym-3000')return `George’s membership and Strength ${state.power||0} must be 25% above the second-highest stat ${second}.`;if(g.id==='mr-isoyamas')return `George’s membership and Defense ${state.resilience||0} must be 25% above the second-highest stat ${second}.`;if(g.id==='total-rebound')return `George’s membership and Speed ${state.reflexes||0} must be 25% above the second-highest stat ${second}.`;if(g.id==='elites')return `George’s membership and Dexterity ${state.precision||0} must be 25% above the second-highest stat ${second}.`;if(g.id==='sports-science')return `Last Round membership and exactly 150 combined Xanax + Ecstasy taken (${drugTotal()} recorded).`;if(g.id==='fight-club')return 'Fight Club invitation required from the game owner.';if(g.type==='standard'){const index=gymCatalog.findIndex(x=>x.id===g.id),previous=index>0?gymCatalog[index-1]:null;return `${g.unlockExp.toLocaleString()} Gym EXP${previous?` and ${previous.name} membership`:''} · ${g.fee?money(g.fee)+' activation fee':'no activation fee'}.`}return 'Specialist requirement not configured.'}
function gymEligibility(g){ensureGymData();if(inHospital())return {ok:false,reason:'While hospitalized, gym training is unavailable.'};if(inJail()&&g.id!=='crims')return {ok:false,reason:'While jailed, only Jail / Crims Gym is available.'};if(g.id==='crims')return {ok:inJail(),reason:gymRequirement(g)};if(g.type==='standard'){const index=gymCatalog.findIndex(x=>x.id===g.id),previous=index>0?gymCatalog[index-1]:null;if(previous&&!state.gym.memberships.includes(previous.id))return {ok:false,reason:`Join ${previous.name} first.`};if(state.gym.exp<g.unlockExp)return {ok:false,reason:`Need ${(g.unlockExp-state.gym.exp).toLocaleString()} more Gym EXP.`};if(!state.gym.memberships.includes(g.id)&&!isOwner()&&state.cash<g.fee)return {ok:false,reason:`Need ${money(g.fee)} for activation.`};return {ok:true,reason:gymRequirement(g)}}if(g.id==='balboas')return {ok:state.gym.memberships.includes('cha-chas')&&defenseRatioOk(),reason:gymRequirement(g)};if(g.id==='frontline')return {ok:state.gym.memberships.includes('cha-chas')&&strengthRatioOk(),reason:gymRequirement(g)};if(['gym-3000','mr-isoyamas','total-rebound','elites'].includes(g.id)){const stat={'gym-3000':'power','mr-isoyamas':'resilience','total-rebound':'reflexes',elites:'precision'}[g.id];return {ok:state.gym.memberships.includes('georges')&&(Number(state[stat])||0)>=1.25*Math.max(...gymStatKeys.filter(k=>k!==stat).map(k=>Number(state[k])||0)),reason:gymRequirement(g)}}if(g.id==='sports-science')return {ok:state.gym.memberships.includes('last-round')&&drugTotal()===150,reason:gymRequirement(g)};if(g.id==='fight-club')return {ok:state.gym.fightClubInvite===true,reason:gymRequirement(g)};return {ok:false,reason:gymRequirement(g)}}
function defenseRatioOk(){const a=(state.resilience||0)+(state.precision||0),b=(state.power||0)+(state.reflexes||0);return a>=1.25*b}
function strengthRatioOk(){const a=(state.power||0)+(state.reflexes||0),b=(state.resilience||0)+(state.precision||0);return a>=1.25*b}
function activateGym(id){ensureGymData();const g=gymById(id),elig=gymEligibility(g);if(!elig.ok){toast(elig.reason);return}if(g.id==='crims'&&!inJail()){toast('Jail / Crims Gym is only available while jailed.');return}if(!state.gym.memberships.includes(g.id)){if(!isOwner()&&state.cash<g.fee){toast(`You need ${money(g.fee)} to activate ${g.name}.`);return}if(!isOwner())state.cash-=g.fee;state.gym.memberships.push(g.id);addActivity('✦','Gym membership activated',`${g.name} · ${g.fee?money(g.fee):'automatic access'}`)}state.gym.active=g.id;save();render();toast(`${g.name} is now your active gym.`)}
function gymRegenMultiplier(){if(!state.gym||!Array.isArray(state.gym.bookEffects))return 1;const now=Date.now();state.gym.bookEffects=state.gym.bookEffects.filter(x=>Number(x.until)>now);return state.gym.bookEffects.filter(x=>x.stat==='regen').reduce((m,x)=>m*(Number(x.multiplier)||1),1)}
function gymModifier(stat){ensureGymData();const now=Date.now();let modifier=1;state.gym.bookEffects=state.gym.bookEffects.filter(x=>Number(x.until)>now);for(const effect of state.gym.bookEffects)if(effect.stat===stat||effect.stat==='all')modifier*=Number(effect.multiplier)||1;if(typeof propertyHasUpgrade==='function'&&propertyHasUpgrade('pool'))modifier*=1.02;return modifier}
function gymActionText(g,stat,amount){const words={power:['loaded the bar','worked through the heavy set','finished a controlled power circuit'],resilience:['braced through the set','held the final rep','stabilized under load'],reflexes:['cut through the speed ladder','snapped through the intervals','finished the quickstep circuit'],precision:['settled into a measured set','hit every mark','completed the control drills']};const set=words[stat]||['completed the session'];const action=set[(state.gym.sessions||0)%set.length];return `At ${g.name}, you ${action}. ${gymStatLabels[stat]} +${amount.toFixed(4)}.`}
function trainGym(stat){if(!activePlayerId||!gymStatKeys.includes(stat))return;if(inHospital()){toast('You are hospitalized and cannot train.');return}ensureGymData();const g=gymById(state.gym.active);const elig=gymEligibility(g);if(!elig.ok){toast(elig.reason);return}const gain=g.gains?.[stat];if(!gain){toast(`${g.name} does not train ${gymStatLabels[stat]}.`);return}const cost=g.energy;if(!spend('stamina',cost)){save();render();return}const happy=Math.max(0,Number(state.morale)||0),total=gymTotals(),a=3.480061091e-7,b=250,c=3.091619094e-6,d=6.82775184551527e-5,e=-0.0301431777;const formula=(a*Math.log(happy+b)+c)*total+d*(happy+b)+e;const books=gymModifier(stat);const amount=Math.max(.01,formula)*gain*cost*books;state[stat]=Number(((Number(state[stat])||0)+amount).toFixed(4));const happyLoss=Math.max(1,Math.round(cost*(.4+Math.random()*.2)));state.morale=Math.max(0,happy-happyLoss);state.gym.exp+=Math.max(1,Math.round(gain*cost));state.gym.sessions++;state.trained=(state.trained||0)+1;state.xp+=Math.max(1,Math.round(amount));state.gym.lastAction=gymActionText(g,stat,amount);addActivity('✦','Gym training complete',`${gymStatLabels[stat]} +${amount.toFixed(4)} · ${cost} Energy · ${g.name}`);save();render();toast(`${gymStatLabels[stat]} +${amount.toFixed(4)} · ${cost} Energy used.`)}
function gymStatCard(g,stat){const gain=g.gains?.[stat],value=Number(state[stat]||0);if(gain==null)return `<div class="gym-stat unavailable"><div class="eyebrow">${gymStatLabels[stat]}</div><h3>Not trained here</h3><p>${gymStatDescriptions[stat]}</p><strong>${value.toFixed(4)}</strong><span class="cost">Unavailable at ${g.name}</span></div>`;const dots=Math.max(0,Math.min(10,Math.round(gain)));return `<div class="gym-stat"><div class="gym-stat-top"><div><div class="eyebrow">${gymStatLabels[stat]}</div><h3>${value.toFixed(4)}</h3></div><span class="gym-gain">×${gain.toFixed(1)}</span></div><p>${gymStatDescriptions[stat]}</p><div class="gym-dots">${Array.from({length:10},(_,i)=>`<i class="${i<dots?'on':''}"></i>`).join('')}</div><span class="cost">${g.energy} Energy · ×${gain.toFixed(1)} gym gain</span><button class="btn gym-train" data-stat="${stat}" ${state.stamina<g.energy?'disabled':''}>Train ${gymStatLabels[stat]}</button></div>`}
function gym(){const gdata=ensureGymData(),active=gymById(gdata.active),next=gymCatalog.find(x=>x.type==='standard'&&!gdata.memberships.includes(x.id)),standard=gymCatalog.filter(x=>x.type==='standard'),specialist=gymCatalog.filter(x=>x.type==='specialist'||x.type==='jail');const membershipRows=list=>list.map(g=>{const member=gdata.memberships.includes(g.id),activeNow=active.id===g.id,elig=gymEligibility(g),label=activeNow?'Active':member?'Switch gym':g.id==='crims'?'Enter jail gym':'Buy membership';return `<div class="gym-ladder-row ${activeNow?'active':''}"><div><strong>${g.name}</strong><span>${g.type==='standard'?`${g.unlockExp.toLocaleString()} EXP unlock · ${g.fee?money(g.fee)+' fee':'automatic'}`:g.type==='jail'?'Automatic while jailed':money(g.fee)+' activation'}</span><small>${elig.reason}</small></div><div class="gym-ladder-action"><span class="tag ${member?'green':''}">${member?'Owned':elig.ok?'Available':'Locked'}</span><button class="btn ${member?'secondary':''} gym-membership" data-gym="${g.id}" ${activeNow||!elig.ok?'disabled':''}>${label}</button></div></div>`}).join('');return layout(`<div class="gym-hero card"><div><div class="eyebrow">PROGRESSION // GYM NETWORK</div><h2>${active.name}</h2><p>Every training session is saved to this player. New players start with a Premier Fitness membership.</p></div><div class="gym-hero-stats"><span>Gym EXP <b>${Math.floor(gdata.exp).toLocaleString()}</b></span><span>${gdata.memberships.length} memberships</span><span>${state.stamina} / ${state.maxStamina} Energy</span></div></div><div class="grid grid-2"><section><div class="section-head"><h2>${active.name} training floor</h2><p>${active.energy} Energy per session · Happy loss 40–60%</p></div><div class="gym-stat-grid">${gymStatKeys.map(stat=>gymStatCard(active,stat)).join('')}</div>${gdata.lastAction?`<div class="card gym-action-log"><div class="label">Latest action</div><p>${gdata.lastAction}</p></div>`:''}</section><aside><div class="card"><div class="panel-title">Gym progress</div><div class="metric">${Math.floor(gdata.exp).toLocaleString()} <small>Gym EXP</small></div><div class="meter"><i style="width:${next?Math.min(100,gdata.exp/Math.max(1,next.unlockExp)*100):100}%"></i></div><p class="muted-note">${next?`${next.name} unlocks at ${next.unlockExp.toLocaleString()} EXP. ${Math.max(0,next.unlockExp-gdata.exp).toLocaleString()} EXP remaining.`:'George’s is the final standard gym. Specialist gyms remain available when their requirements are met.'}</p><div class="resource"><span>Sessions completed</span><b>${gdata.sessions}</b></div><div class="resource"><span>Trainable now</span><b>${Math.floor(state.stamina/active.energy)} sessions</b></div></div><div class="card"><div class="panel-title">Training formula</div><p class="muted-note">Gains use the supplied Happy, total-stat, gym multiplier, energy, and active-book modifiers. Every session permanently saves the fractional stat increase and spends 40–60% of its Energy as Happy.</p></div></aside></div><div class="section-head"><h2>Standard gym ladder</h2><p>24 gyms · unlock in order</p></div><div class="card gym-ladder">${membershipRows(standard)}</div><div class="section-head"><h2>Specialist gyms</h2><p>Conditional memberships</p></div><div class="card gym-ladder">${membershipRows(specialist)}</div><div class="section-head"><h2>Gym books</h2><p>Temporary training modifiers</p></div><div class="card gym-books">${gymBooks.map(b=>`<div class="list-row"><div><strong>${b[1]}</strong><span>${b[2]}</span></div><span class="tag">${gdata.bookEffects.some(x=>x.id===b[0]&&x.until>Date.now())?'Active':'Read from Items'}</span></div>`).join('')}</div>`, 'Progression // Gym', 'Build the body that survives.', 'Train at the right floor, unlock stronger multipliers, and keep every stat increase attached to your player account.');}
