function propertyDefaultRecord(id='shack'){return {id,upgrades:{},staff:{},vault:0,upkeep:0,lastUpkeepAt:Date.now(),vaultTransactions:[]}}
function ensurePropertyData(){if(!state.property||typeof state.property!=='object')state.property={homeId:'shack',owned:[propertyDefaultRecord()],lease:null,leaseOffers:[],vaultShared:false};if(!Array.isArray(state.property.owned))state.property.owned=[propertyDefaultRecord(state.property.id||'shack')];if(!state.property.owned.length)state.property.owned=[propertyDefaultRecord('shack')];for(const record of state.property.owned){if(!record.upgrades||typeof record.upgrades!=='object')record.upgrades={};if(!record.staff||typeof record.staff!=='object')record.staff={};if(!Number.isFinite(record.vault))record.vault=0;if(!Number.isFinite(record.upkeep))record.upkeep=0;if(!Number.isFinite(record.lastUpkeepAt))record.lastUpkeepAt=Date.now();if(!Array.isArray(record.vaultTransactions))record.vaultTransactions=[]}if(!propertyCatalog.some(x=>x.id===state.property.homeId))state.property.homeId=state.property.owned[0].id;if(!Array.isArray(state.property.leaseOffers))state.property.leaseOffers=[];return state.property}
function propertyInfo(id){return propertyCatalog.find(x=>x.id===id)||propertyCatalog[0]}
function propertyRecord(id){const p=ensurePropertyData();return p.owned.find(x=>x.id===id)||(p.lease&&p.lease.id===id?p.lease:null)}
function propertyHomeRecord(){const p=ensurePropertyData();return propertyRecord(p.homeId)||p.owned[0]}
function propertyHomeInfo(){return propertyInfo(propertyHomeRecord().id)}
function propertyStaffDaily(record){return Object.entries(record?.staff||{}).reduce((sum,[type,level])=>{const row=propertyStaffCatalog[type]?.find(x=>x.level===Number(level));return sum+(row?.daily||0)},0)}
function propertyStaffHappy(record){return Object.entries(record?.staff||{}).reduce((sum,[type,level])=>{const row=propertyStaffCatalog[type]?.find(x=>x.level===Number(level));return sum+(row?.happy||0)},0)}
function propertyHasUpgrade(id,record=propertyHomeRecord()){if(!record)return false;if(id==='vault')return Number(record.upgrades.vault||0)>0;if(id==='medical')return Number(record.upgrades.medical||0)>0;return !!record.upgrades[id]}
function propertyUpgradeAllowed(g,info){if(info.index<g.minIndex)return false;if(g.kind==='vault')return info.index>=11;if(g.kind==='medical')return info.index>=12;if(g.id==='airstrip')return info.index>=13;if(g.id==='yacht')return info.index>=13;return true}
function propertyUpgradeState(g,record){if(g.kind==='vault')return Number(record.upgrades.vault||0)>=g.level;if(g.kind==='medical')return Number(record.upgrades.medical||0)>=g.level;return !!record.upgrades[g.id]}
function propertyUpgradeCost(g,info){return Math.max(0,Math.round((g.cost?.(info)||0)*(state.property?.discounts?.elt?0.9:1)*(state.property?.discounts?.broker?0.9:1)))}
function propertyUpgradeHappy(g,info){return Number(g.happy?.(info)||0)}
function propertyExpireLease(now=Date.now()){const p=state.property;if(!p?.lease||Number(p.lease.leaseExpiresAt)>now)return;if(p.homeId===p.lease.id)p.homeId=p.owned?.[0]?.id||'shack';p.lease=null;addActivity('⌂','Property lease expired','Residence returned to your owned home.')}
function propertyAccrueUpkeep(now=Date.now()){propertyExpireLease(now);const record=propertyHomeRecord();if(!record)return;const last=Number(record.lastUpkeepAt)||now;if(last>now){record.lastUpkeepAt=now;return}const days=Math.floor((now-last)/86400000);if(days<1)return;const waived=state.company?.type&&/lingerie/i.test(state.company.type)&&Number(state.company.stars||0)>=7;if(!waived)record.upkeep+=days*(propertyInfo(record.id).upkeep+propertyStaffDaily(record));record.lastUpkeepAt=last+days*86400000}
function propertyDebtPenalty(record,info){const threshold=info.cost*.1;if(!threshold||record.upkeep<=threshold)return 0;return (record.upkeep-threshold)/info.cost*2.5}
function propertyMaxHappy(){propertyAccrueUpkeep();const record=propertyHomeRecord(),info=propertyInfo(record.id);let value=info.baseHappy;for(const g of propertyUpgradeCatalog)if(propertyUpgradeState(g,record))value+=propertyUpgradeHappy(g,info);value+=propertyStaffHappy(record);return Math.max(0,Math.floor(value-propertyDebtPenalty(record,info)))}
function propertyBenefits(record=propertyHomeRecord()){const info=propertyInfo(record.id),benefits=[];if(propertyHasUpgrade('pool',record))benefits.push('Swimming pool · +2% Gym gains');if(propertyHasUpgrade('shooting-small',record)||propertyHasUpgrade('shooting-medium',record)||propertyHasUpgrade('shooting-large',record))benefits.push('Advanced shooting range · +2% damage');if(propertyHasUpgrade('medical',record))benefits.push('Medical facility · extra Life regeneration');if(propertyHasUpgrade('airstrip',record))benefits.push('Airstrip · free, faster travel and 15-item transport');if(propertyHasUpgrade('yacht',record))benefits.push('Private yacht · +500 Happy');return benefits}
function propertyCanStaff(info,type){const minimum={maid:8,butler:8,guard:8,doctor:9,pilot:13}[type]||99;return info.index>=minimum}
function propertyDiscountPercent(){return (state.property?.discounts?.elt?10:0)+(state.property?.discounts?.broker?10:0)+(state.property?.discounts?.law2910?5:0)}
function propertyPurchaseCost(info){return Math.round(info.cost*(1-propertyDiscountPercent()/100))}
function buyProperty(id){ensurePropertyData();const info=propertyInfo(id);if(state.property.owned.some(x=>x.id===id)){toast('You already own this property.');return}const price=propertyPurchaseCost(info);if(!isOwner()&&state.cash<price){toast(`You need ${money(price)} to buy the ${info.name}.`);return}if(!isOwner())state.cash-=price;state.property.owned.push(propertyDefaultRecord(id));addActivity('⌂','Property purchased',`${info.name} · ${money(price)}`);save();render();toast(`${info.name} purchased. Move in when ready.`)}
function moveIntoProperty(id){ensurePropertyData();const target=propertyRecord(id),current=propertyHomeRecord();if(!target){toast('That property is not available.');return}if(state.property.homeId===id){toast('You already live there.');return}if((current.upkeep||0)>0||Object.values(current.staff||{}).some(Boolean)){toast('Move out requires clearing upkeep and firing all staff first.');return}state.property.homeId=id;state.property.lease=state.property.lease?.id===id?state.property.lease:null;addActivity('⌂','Moved into property',propertyInfo(id).name);save();render();toast(`You moved into the ${propertyInfo(id).name}.`)}
function payPropertyUpkeep(){const record=propertyHomeRecord();propertyAccrueUpkeep();const amount=Math.max(0,Math.floor(Number(document.getElementById('propertyUpkeepAmount')?.value)||record.upkeep));if(amount<=0){toast('There is no outstanding upkeep.');return}const paid=isOwner()?amount:Math.min(amount,state.cash);if(!isOwner())state.cash-=paid;record.upkeep=Math.max(0,record.upkeep-paid);addActivity('⌂','Property upkeep paid',money(paid));save();render();toast(record.upkeep?`Paid ${money(paid)}. ${money(record.upkeep)} remains.`:'Property upkeep cleared.')}
function upgradeProperty(id){const record=propertyHomeRecord(),info=propertyHomeInfo(),g=propertyUpgradeCatalog.find(x=>x.id===id);if(!g||!record){toast('Upgrade unavailable.');return}if(!propertyUpgradeAllowed(g,info)){toast(`${g.name} is not available for a ${info.name}.`);return}if(propertyUpgradeState(g,record)){toast('That upgrade is already installed.');return}if(g.kind==='vault'&&Number(record.upgrades.vault||0)!==g.level-1){toast('Vault upgrades must be purchased in order.');return}if(g.kind==='medical'&&Number(record.upgrades.medical||0)!==g.level-1){toast('Medical facility upgrades must be purchased in order.');return}const cost=propertyUpgradeCost(g,info);if(!isOwner()&&state.cash<cost){toast(`You need ${money(cost)} for ${g.name}.`);return}if(!isOwner())state.cash-=cost;if(g.kind==='vault')record.upgrades.vault=g.level;else if(g.kind==='medical')record.upgrades.medical=g.level;else record.upgrades[g.id]=true;addActivity('⌂','Property upgraded',`${info.name} · ${g.name} · ${money(cost)}`);save();render();toast(`${g.name} installed for ${money(cost)}.`)}
function hirePropertyStaff(type){const record=propertyHomeRecord(),info=propertyHomeInfo(),rows=propertyStaffCatalog[type];if(!record||!rows||!propertyCanStaff(info,type)){toast(`${info.name} cannot hire this staff role.`);return}const current=Number(record.staff[type]||0),next=rows.find(x=>x.level===current+1);if(!next){toast(`${type[0].toUpperCase()+type.slice(1)} service is at its maximum.`);return}record.staff[type]=next.level;addActivity('⌂','Property staff hired',`${next.name} · ${money(next.daily)} daily`);save();render();toast(`${next.name} hired. Daily cost: ${money(next.daily)}.`)}
function firePropertyStaff(type){const record=propertyHomeRecord();if(!record||!record.staff[type]){toast('No staff member to fire.');return}delete record.staff[type];addActivity('⌂','Property staff fired',type[0].toUpperCase()+type.slice(1)+' service');save();render();toast(`${type[0].toUpperCase()+type.slice(1)} service fired.`)}
function propertyVaultCapacity(record=propertyHomeRecord()){const level=Number(record?.upgrades?.vault||0);return [0,100000000,300000000,500000000,1000000000][level]||0}
function propertyVaultTransaction(record,type,amount){record.vaultTransactions=Array.isArray(record.vaultTransactions)?record.vaultTransactions:[];record.vaultTransactions.unshift({type,amount,at:Date.now(),playerId:state.playerId});record.vaultTransactions=record.vaultTransactions.slice(0,40)}
function depositPropertyVault(){const record=propertyHomeRecord(),capacity=propertyVaultCapacity(record),amount=Math.floor(Number(document.getElementById('propertyVaultAmount')?.value)||0);if(state.property.lease?.id===record.id){toast('Vault access is disabled in rented properties.');return}if(!capacity){toast('Install a vault upgrade first.');return}if(amount<=0||(!isOwner()&&state.cash<amount)){toast('Enter an amount available in your wallet.');return}if(record.vault+amount>capacity){toast(`That deposit exceeds the ${money(capacity)} vault capacity.`);return}if(!isOwner())state.cash-=amount;record.vault+=amount;propertyVaultTransaction(record,'Deposit',amount);save();render();toast(`${money(amount)} deposited into the property vault.`)}
function withdrawPropertyVault(){const record=propertyHomeRecord(),amount=Math.floor(Number(document.getElementById('propertyVaultAmount')?.value)||0);if(state.property.lease?.id===record.id){toast('Vault access is disabled in rented properties.');return}if(!propertyVaultCapacity(record)||amount<=0||record.vault<amount){toast('Enter an amount available in this vault.');return}if(!isOwner())state.cash+=amount;record.vault-=amount;propertyVaultTransaction(record,'Withdraw',amount);save();render();toast(`${money(amount)} withdrawn from the property vault.`)}
function sellProperty(id){ensurePropertyData();const record=state.property.owned.find(x=>x.id===id),info=propertyInfo(id);if(!record||id==='shack'){toast('That property cannot be sold.');return}if(state.property.homeId===id){toast('Move into another property before selling this one.');return}if(Object.values(record.staff||{}).some(Boolean)){toast('Fire all staff before selling the property.');return}const proceeds=Math.max(0,info.value-(record.upkeep||0));state.cash+=proceeds;state.property.owned=state.property.owned.filter(x=>x!==record);addActivity('⌂','Property sold',`${info.name} · +${money(proceeds)}`);save();render();toast(`${info.name} sold for ${money(proceeds)}.`)}
function createPropertyLease(){const propertyId=document.getElementById('leaseProperty')?.value,targetId=document.getElementById('leaseTarget')?.value.trim(),price=Math.floor(Number(document.getElementById('leasePrice')?.value)||0),days=Math.max(1,Math.min(100,Math.floor(Number(document.getElementById('leaseDays')?.value)||1)));const record=state.property.owned.find(x=>x.id===propertyId);if(!record||propertyId==='shack'){toast('Choose an owned property to lease.');return}if(state.property.homeId===propertyId){toast('Move out before offering your current home.');return}if(!/^\d{7}$/.test(targetId)||price<0){toast('Enter a valid target player ID and upfront price.');return}state.property.leaseOffers.unshift({id:'lease-'+Date.now(),propertyId,targetId,price,days,upgrades:structuredClone(record.upgrades),createdAt:Date.now(),status:'Offered'});save();render();toast(`Lease offer sent to [${targetId}] for ${days} days.`)}
function acceptPropertyLease(id){const offer=state.property.leaseOffers.find(x=>x.id===id);if(!offer||String(offer.targetId)!==String(state.playerId)){toast('That lease offer is not addressed to this player.');return}if(!isOwner()&&state.cash<offer.price){toast('You need the upfront lease price.');return}if(!isOwner())state.cash-=offer.price;const source=state.property.owned.find(x=>x.id===offer.propertyId);const info=propertyInfo(offer.propertyId);const expiry=new Date(Date.now()+offer.days*86400000);expiry.setHours(3,30,0,0);state.property.lease={id:offer.propertyId,name:info.name,upgrades:offer.upgrades,staff:{},vault:0,upkeep:0,lastUpkeepAt:Date.now(),leaseExpiresAt:expiry.getTime(),ownerId:state.playerId};state.property.homeId=offer.propertyId;state.property.leaseOffers=state.property.leaseOffers.filter(x=>x!==offer);addActivity('⌂','Property lease accepted',`${info.name} · ${offer.days} days`);save();render();toast(`Lease accepted. You have ${offer.days} days in the ${info.name}.`)}
function togglePropertyVault(){if(!state.marriage||state.marriage.status!=='Married'){toast('You need to be married before sharing a property vault.');return}state.marriage.sharedVault=!state.marriage.sharedVault;state.property.vaultShared=state.marriage.sharedVault;save();render();toast(state.marriage.sharedVault?'Property vault shared with your spouse.':'Property vault sharing disabled.')}
function propertyPage(){const p=ensurePropertyData();propertyAccrueUpkeep();const home=propertyHomeRecord(),info=propertyInfo(home.id),maxHappy=propertyMaxHappy(),capacity=propertyVaultCapacity(home),discount=propertyDiscountPercent(),owned=p.owned,offers=p.leaseOffers.filter(x=>String(x.targetId)===String(state.playerId));const upgradeRows=propertyUpgradeCatalog.map(g=>{const allowed=propertyUpgradeAllowed(g,info),installed=propertyUpgradeState(g,home),cost=propertyUpgradeCost(g,info);return `<div class="list-row property-upgrade-row"><div><strong>${g.name}</strong><span>${g.desc} · ${money(cost)}${g.kind==='vault'?` · capacity ${money(g.capacity)}`:''}</span></div><button class="btn property-upgrade" data-property-upgrade="${g.id}" ${!allowed||installed?'disabled':''}>${installed?'Installed':allowed?'Buy upgrade':'Unavailable'}</button></div>`}).join('');const staffRows=Object.entries(propertyStaffCatalog).map(([type,rows])=>{const level=Number(home.staff[type]||0),current=rows.find(x=>x.level===level),next=rows.find(x=>x.level===level+1);return `<div class="list-row"><div><strong>${current?.name||type[0].toUpperCase()+type.slice(1)+' service'}</strong><span>${current?money(current.daily)+' daily · +'+current.happy+' Happy':'Not hired'}${next?' · next '+money(next.daily)+'/day':''}</span></div><div class="property-staff-actions"><button class="btn secondary property-staff-hire" data-property-staff="${type}" ${!next||!propertyCanStaff(info,type)?'disabled':''}>${next?'Hire / upgrade':'Maxed'}</button><button class="btn property-staff-fire" data-property-staff-fire="${type}" ${level?'':'disabled'}>Fire</button></div></div>`}).join('');const ownedRows=propertyCatalog.map(x=>{const record=owned.find(r=>r.id===x.id),current=p.homeId===x.id,price=propertyPurchaseCost(x);return `<div class="property-list-row ${current?'current':''}"><div><strong>${x.name}</strong><span>Base Happy ${x.baseHappy.toLocaleString()} · ${money(x.upkeep)} daily · Agency value ${money(x.value)}</span></div><div class="property-actions"><span class="tag ${record?'green':''}">${current?'Current home':record?'Owned':'Available'}</span>${record?(current?'':'<button class="btn secondary property-move" data-property-id="'+x.id+'">Move in</button>'):'<button class="btn property-buy" data-property-id="'+x.id+'" '+(!isOwner()&&state.cash<price?'disabled':'')+'>Buy · '+money(price)+'</button>'}${record&&!current&&x.id!=='shack'?'<button class="btn secondary property-sell" data-property-id="'+x.id+'">Sell</button>':''}</div></div>`}).join('');return layout(`<div class="property-hero card"><div><div class="eyebrow">RESIDENTIAL // ESTATE AGENCY</div><h2>${info.name}</h2><p>Live in a property to raise your maximum Happy. Upgrade facilities, hire staff, manage upkeep, and protect your vault.</p></div><div class="property-hero-stats"><span>Max Happy <b>${maxHappy.toLocaleString()}</b></span><span>Daily upkeep <b>${money(propertyInfo(home.id).upkeep+propertyStaffDaily(home))}</b></span><span>Wallet <b>${walletLabel()}</b></span></div></div><div class="grid grid-2"><section><div class="grid grid-4 property-metrics"><div class="card"><div class="label">Base Happy</div><div class="metric">${info.baseHappy.toLocaleString()}</div></div><div class="card"><div class="label">Current Happy cap</div><div class="metric">${maxHappy.toLocaleString()}</div></div><div class="card"><div class="label">Upkeep debt</div><div class="metric">${money(home.upkeep||0)}</div></div><div class="card"><div class="label">Vault</div><div class="metric">${capacity?money(home.vault||0):'Unavailable'}</div></div></div><div class="card"><div class="panel-title">Property status</div><div class="resource"><span>Residence</span><b>${info.name}</b></div><div class="resource"><span>Upkeep + staff due daily</span><b>${money(info.upkeep+propertyStaffDaily(home))}</b></div><div class="resource"><span>Debt happiness penalty</span><b>${propertyDebtPenalty(home,info).toFixed(2)}</b></div><div class="resource"><span>Discounts</span><b>${discount?discount+'%':'None'}</b></div><div class="form-row property-form-row"><input id="propertyUpkeepAmount" class="name-input" inputmode="numeric" placeholder="Amount to pay"/><button class="btn" id="propertyPayUpkeep">Pay upkeep</button>${home.upkeep?'':'<span class="tag green">Upkeep clear</span>'}</div></div><div class="section-head"><h2>Facilities and upgrades</h2><p>Upgrades are permanent</p></div><div class="card property-upgrades">${upgradeRows}</div></section><aside><div class="card"><div class="panel-title">Property benefits</div><div class="list">${propertyBenefits(home).map(x=>`<div class="list-row"><strong>${x}</strong><span class="tag green">Active</span></div>`).join('')||'<div class="empty">Upgrade this residence to unlock facilities and perks.</div>'}</div></div><div class="card"><div class="panel-title">Vault ${capacity?`· ${money(capacity)} capacity`:'· unavailable'}</div><p class="muted-note">Rented properties cannot access a vault. Vault sharing is disabled until marriage and can be revoked at any time.</p><div class="resource"><span>Balance</span><b>${capacity?money(home.vault||0):'Unavailable'}</b></div><div class="form-row property-form-row"><input id="propertyVaultAmount" class="name-input" inputmode="numeric" placeholder="Credits"/><button class="btn secondary" id="propertyDepositVault" ${capacity?'':'disabled'}>Deposit</button><button class="btn" id="propertyWithdrawVault" ${capacity?'':'disabled'}>Withdraw</button></div><button class="btn secondary" id="propertyToggleVault">${state.marriage?.sharedVault?'Stop sharing vault':'Share vault with spouse'}</button><div class="list property-transactions">${(home.vaultTransactions||[]).slice(0,5).map(t=>`<div class="list-row"><strong>${t.type}</strong><span>${money(t.amount)} · ${new Date(t.at).toLocaleString()}</span></div>`).join('')||'<div class="empty">No vault transactions.</div>'}</div></div></aside></div><div class="section-head"><h2>Property staff</h2><p>Daily fees and Happy bonuses</p></div><div class="card property-staff">${staffRows}</div><div class="section-head"><h2>Owned properties</h2><p>${owned.length} owned · move between residences</p></div><div class="card property-list">${ownedRows}</div><div class="section-head"><h2>Lease market</h2><p>Upfront price · maximum 100 days</p></div><div class="grid grid-2"><section class="card"><div class="panel-title">Offer a lease</div><p class="muted-note">Lease terms lock when accepted. The tenant pays upfront; rent does not include daily staff fees.</p><div class="form-row"><select id="leaseProperty" class="name-input">${owned.filter(x=>x.id!=='shack'&&x.id!==p.homeId).map(x=>`<option value="${x.id}">${propertyInfo(x.id).name}</option>`).join('')||'<option value="">No vacant property</option>'}</select><input id="leaseTarget" class="name-input" placeholder="Tenant player ID" inputmode="numeric"/><input id="leasePrice" class="name-input" placeholder="Upfront price" inputmode="numeric"/><input id="leaseDays" class="name-input" placeholder="Days (1–100)" inputmode="numeric" value="7"/><button class="btn" id="propertyCreateLease">Offer lease</button></div><div class="list">${p.leaseOffers.filter(x=>x.targetId!==state.playerId).slice(0,6).map(x=>`<div class="list-row"><strong>${propertyInfo(x.propertyId).name}</strong><span>[${x.targetId}] · ${x.days} days · ${money(x.price)} · ${x.status}</span></div>`).join('')||'<div class="empty">No outgoing lease offers.</div>'}</div></section><aside class="card"><div class="panel-title">Incoming lease offers</div><div class="list">${offers.map(x=>`<div class="list-row"><div><strong>${propertyInfo(x.propertyId).name}</strong><span>${x.days} days · ${money(x.price)} upfront</span></div><button class="btn property-lease-accept" data-lease-id="${x.id}">Accept</button></div>`).join('')||'<div class="empty">No incoming offers.</div>'}</div></aside></div>`, 'Residential // Properties', 'Make a place worth defending.', 'The right property turns time, money, and upgrades into a larger Happy ceiling and better options.');}
function jailRemainingMs(){return Math.max(0,Number(state.jailUntil||0)-Date.now())}
function jailRemainingLabel(){const mins=Math.ceil(jailRemainingMs()/60000),hours=Math.floor(mins/60);return hours?`${hours}h ${mins%60}m`:mins+'m'}
function sendToJail(minutes,reason='City law violation'){state.jailUntil=Date.now()+Math.max(1,minutes)*60000;state.jailReason=reason;state.jailHistory=Array.isArray(state.jailHistory)?state.jailHistory:[];state.jailHistory.unshift({reason,at:Date.now(),minutes});state.jailHistory=state.jailHistory.slice(0,30);addActivity('⚖','Sent to jail',`${reason} · ${minutes} minutes`)}
function lawBailDiscount(){let discount=Number(state.education?.lawBailDiscount||0);if(state.education?.law2990)discount=Math.max(discount,.15);if(state.education?.bachelorOfLaw)discount=Math.max(discount,.5);if(state.job?.sector==='Law'&&Number(state.job?.stars||0)>=1)discount=Math.max(discount,.5);return Math.min(.5725+(.5*(state.job?.sector==='Law'?1:0)),discount)}
function bustChance(target){const remaining=Math.max(1,jailRemainingMs()/60000),level=Number(target.level)||1,ownLevel=Number(state.level)||1,completed=Number(state.busts||0);let chance=.24+Math.min(.2,completed*.002)+Math.max(-.08,Math.min(.12,(ownLevel-level)*.01))-Math.min(.16,remaining/1800);if(state.education?.lawBustingBonus)chance+=Number(state.education.lawBustingBonus);if(state.job?.sector==='Law')chance+=.15;chance+=Math.min(.5,Number(state.faction?.perks?.criminality||0));return Math.max(.03,Math.min(.95,chance))}
function selfBust(){if(!inJail()){toast('You are not in jail.');return}const cost=state.education?.law2990?Math.ceil(state.maxNerve/3):Math.ceil(state.maxNerve/2);if(!spend('nerve',cost)){save();render();return}state.selfBusts=(state.selfBusts||0)+1;const chance=Math.max(.05,Math.min(.9,.3+(Number(state.level)||1)*.01-(jailRemainingMs()/6000000)+(state.education?.lawBustingBonus||0)));if(Math.random()<chance){state.jailUntil=0;state.jailReason='';state.busts=(state.busts||0)+1;addActivity('⚖','Self bust successful',`Escaped for ${cost} Nerve`);toast('You busted yourself out of jail.')}else{const extra=10+Math.floor(Math.random()*51);state.jailUntil+=extra*60000;addActivity('⚖','Self bust failed',`+${extra} minutes jail time`);toast(`Self bust failed. Jail extended by ${extra} minutes.`)}save();render()}
function buyBail(){if(!inJail()){toast('You are not in jail.');return}const minutes=Math.max(1,Math.ceil(jailRemainingMs()/60000)),cost=Math.ceil(100*minutes*Math.max(1,Number(state.level)||1)*(1-lawBailDiscount()));if(!isOwner()&&state.cash<cost){toast(`You need ${money(cost)} to buy bail.`);return}if(!isOwner())state.cash-=cost;state.jailUntil=0;state.jailReason='';addActivity('⚖','Bail paid',money(cost));save();render();toast(`Bail paid for ${money(cost)}. You are free.`)}
function bustPlayer(){const id=document.getElementById('bustTargetId')?.value.trim();if(!/^\d{7}$/.test(id)){toast('Enter a valid jailed player ID.');return}if(String(id)===String(state.playerId)){toast('Use Self bust for your own sentence.');return}let target=null;try{target=JSON.parse(localStorage.getItem(playerSaveKey(id))||'null')}catch{}if(!target||Number(target.jailUntil)<=Date.now()){toast('That player is not currently jailed.');return}const cost=Math.max(2,5-Math.min(3,Number(state.faction?.perks?.criminalityBustCost||0)));if(!spend('nerve',cost)){save();render();return}const chance=bustChance(target);const roll=Math.random();if(roll<chance){target.jailUntil=0;target.jailReason='';target.busts=(target.busts||0)+1;target.activity=[{icon:'⚖',title:'Busted out of jail',desc:`Player [${state.playerId}] freed you.`,time:'Just now'},...(target.activity||[])].slice(0,6);localStorage.setItem(playerSaveKey(id),JSON.stringify(target));state.busts=(state.busts||0)+1;addActivity('⚖','Successful bust',`[${id}] freed · ${Math.round(chance*100)}% chance`);toast(`Successful bust. [${id}] is free.`)}else if(roll<chance+.15){sendToJail(60+Math.floor(Math.random()*121),'Caught attempting a bust');addActivity('⚖','Bust failed',`[${id}] remains jailed · you were caught`);toast('Bust failed and you were sent to jail.')}else{addActivity('⚖','Bust failed',`[${id}] remains jailed · ${Math.round(chance*100)}% chance`);toast('Bust failed. The jailed player remains in custody.')}save();render()}
function jailPage(){const jailed=inJail(),lawyer=(state.inventory||[]).find(i=>/Lawyer Business Card/i.test(i.name)&&i.qty>0),cost=jailed?Math.ceil(100*Math.max(1,Math.ceil(jailRemainingMs()/60000))*Math.max(1,Number(state.level)||1)*(1-lawBailDiscount())):0;return layout(`<div class="jail-hero card"><div><div class="eyebrow">CITY CENTER // BLACKHARBOR JAIL</div><h2>${jailed?'You are in custody':'You are free'}</h2><p>${jailed?`${state.jailReason||'City law violation'} · ${jailRemainingLabel()} remaining`:'No active sentence. Players who break city law are sent here.'}</p></div><span class="tag ${jailed?'':'green'}">${jailed?'INMATE':'CLEAR'}</span></div><div class="grid grid-2"><section><div class="card"><div class="panel-title">Your options</div>${jailed?`<div class="list"><div class="list-row"><div><strong>Self bust</strong><span>Costs ${state.education?.law2990?Math.ceil(state.maxNerve/3):Math.ceil(state.maxNerve/2)} Nerve · chance improves with Law education</span></div><button class="btn" id="selfBustBtn" ${state.nerve<(state.education?.law2990?Math.ceil(state.maxNerve/3):Math.ceil(state.maxNerve/2))?'disabled':''}>Attempt</button></div><div class="list-row"><div><strong>Buy bail</strong><span>${money(cost)} · ${Math.round(lawBailDiscount()*100)}% discount applied</span></div><button class="btn secondary" id="buyBailBtn" ${isOwner()||state.cash>=cost?'':'disabled'}>Pay bail</button></div>${lawyer?`<div class="list-row"><div><strong>Lawyer Business Card</strong><span>Instantly leaves jail · consumes one card</span></div><button class="btn secondary" id="useLawyerCard">Use card</button></div>`:''}</div>`:'<div class="empty">No sentence is active. You can still attempt a bust on another inmate or return to the city.</div>'}</div><div class="card"><div class="panel-title">Busting another player</div><p class="muted-note">Each bust costs 5 Nerve, reduced by Criminality faction perks. A failed attempt can send you to jail for 1–3 hours.</p><div class="form-row"><input id="bustTargetId" class="name-input" placeholder="Jailed player ID" inputmode="numeric"><button class="btn" id="bustPlayerBtn" ${state.nerve<2?'disabled':''}>Attempt bust</button></div></div></section><aside><div class="card"><div class="panel-title">Crims Gym</div><p class="muted-note">While jailed, only Crims Gym is available. Train Strength, Speed, and Defense for 5 Energy; Dexterity is unavailable. Drugs, Energy Drinks, and faction armory restores remain usable.</p><button class="btn" data-view="gym">Open Crims Gym</button></div><div class="card"><div class="panel-title">Jail record</div><div class="resource"><span>Completed busts</span><b>${state.busts||0}</b></div><div class="resource"><span>Self bust attempts</span><b>${state.selfBusts||0}</b></div><div class="list">${(state.jailHistory||[]).slice(0,6).map(x=>`<div class="list-row"><strong>${x.reason}</strong><span>${x.minutes} minutes · ${new Date(x.at).toLocaleString()}</span></div>`).join('')||'<div class="empty">No jail history.</div>'}</div></div></aside></div>`, 'City Services // Jail', jailed?'Escape custody.':'City Jail', jailed?'Use nerve, education, bail, or a lawyer to get out.':'The jail doors are open. Keep your record clean.');}
function inHospital(){return Number(state.hospitalUntil)>Date.now()}
function hospitalRemainingMs(){return Math.max(0,Number(state.hospitalUntil||0)-Date.now())}
function hospitalRemainingLabel(){const mins=Math.ceil(hospitalRemainingMs()/60000),hours=Math.floor(mins/60);return hours?hours+'h '+(mins%60)+'m':mins+'m'}
function sendToHospital(minutes,reason='Combat injuries',attackerId=''){const duration=Math.max(1,Math.floor(minutes));state.hospitalUntil=Date.now()+duration*60000;state.hospitalReason=reason;state.hospitalHistory=Array.isArray(state.hospitalHistory)?state.hospitalHistory:[];state.hospitalHistory.unshift({reason,minutes:duration,attackerId,at:Date.now()});state.hospitalHistory=state.hospitalHistory.slice(0,30);state.vitality=Math.max(1,Math.min(Number(state.vitality)||1,Math.floor((Number(state.maxVitality)||100)*.35)));addActivity('✚','Admitted to hospital',reason+' · '+duration+' minutes')}
function hospitalTreatment(){if(!inHospital()){toast('You are not in hospital.');return}const fee=2500;if(!isOwner()&&state.cash<fee){toast('Treatment costs '+money(fee)+'.');return}if(!isOwner())state.cash-=fee;state.hospitalUntil=0;state.hospitalReason='';state.vitality=state.maxVitality;addActivity('✚','Hospital treatment','Discharged at full Vitality');save();render();toast('Hospital treatment complete. You are discharged.')}
function hospitalPage(){const admitted=inHospital(),remaining=admitted?hospitalRemainingLabel():'No active admission',history=(state.hospitalHistory||[]).slice(0,8).map(x=>'<div class="list-row"><strong>'+x.reason+'</strong><span>'+x.minutes+' minutes · '+new Date(x.at).toLocaleString()+'</span></div>').join('');return layout('<div class="hospital-hero card"><div><div class="eyebrow">CITY CENTER // SAINT VEY HOSPITAL</div><h2>'+(admitted?'Under medical care':'Hospital clear')+'</h2><p>'+(admitted?(state.hospitalReason||'Injuries')+' · '+remaining+' remaining':'The hospital treats combat injuries, overdoses, and other critical conditions.')+'</p></div><span class="tag '+(admitted?'':'green')+'">'+(admitted?'ADMITTED':'DISCHARGED')+'</span></div><div class="grid grid-2"><section><div class="card"><div class="panel-title">Patient status</div><div class="resource"><span>Vitality</span><b>'+state.vitality+' / '+state.maxVitality+'</b></div><div class="meter"><i style="width:'+Math.min(100,state.vitality/Math.max(1,state.maxVitality)*100)+'%"></i></div><div class="resource"><span>Time remaining</span><b>'+remaining+'</b></div>'+(admitted?'<button class="btn" id="hospitalTreatment">Pay for immediate treatment · 2,500 cr</button>':'<div class="empty">You are healthy enough to leave. Keep an eye on Vitality before starting another fight.</div>')+'</div><div class="card"><div class="panel-title">Hospital rules</div><div class="list"><div class="list-row"><strong>Admission</strong><span>Combat losses, overdose, or severe city incidents</span></div><div class="list-row"><strong>Restrictions</strong><span>Attacking, trading stocks, and travel are unavailable while admitted</span></div><div class="list-row"><strong>Recovery</strong><span>Wait for the timer or pay for immediate treatment</span></div><div class="list-row"><strong>Medical facility</strong><span>Property medical upgrades improve recovery effects</span></div></div></div></section><aside><div class="card"><div class="panel-title">Medical record</div><div class="list">'+(history||'<div class="empty">No hospital visits recorded.</div>')+'</div></div><button class="btn secondary" data-view="overview">Return to Overview</button></aside></div>', 'Health // Hospital', admitted?'Recover and return to the city.':'Hospital services', admitted?'Your actions are restricted until treatment is complete.':'Saint Vey Hospital keeps every operative in the fight.')}
const newspaperSeedArticles=[
 {id:'gw-001',title:'The city map wakes up',author:'Gore-Wars City Times',date:'2026-10-04',body:'Blackharbor districts are now connected through the RESPO map. Crews are already watching the blocks that matter.'},
 {id:'gw-002',title:'Faction walls move at midnight',author:'City Desk',date:'2026-10-03',body:'Territory control is changing the balance of power. Respect, rackets, and organized crimes all follow the map.'},
 {id:'gw-003',title:'A better way to train',author:'George',date:'2026-10-02',body:'Energy is finite. Pick the right gym, spend your Happy carefully, and keep building the stats you need.'},
 {id:'gw-004',title:'The East Side opens late',author:'Night Editor',date:'2026-10-01',body:'Shops are stocked across Blackharbor. Items bought in the city go straight into the player Items inventory.'},
 {id:'gw-005',title:'Bounties draw a crowd',author:'Crime Desk',date:'2026-09-30',body:'A reward is only useful when someone can find it. Check the classified pages before choosing your next target.'},
 {id:'gw-006',title:'Law education pays twice',author:'Civic Affairs',date:'2026-09-29',body:'Law classes improve busting and can reduce bail. The jail doors are heavy, but preparation helps.'},
 {id:'gw-007',title:'The first names of Blackharbor',author:'Archives',date:'2026-09-28',body:'Every operative leaves a mark. The Chronicle archive keeps the city’s turning points in one place.'}
];
function newspaperEscape(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function ensureNewspaperData(){if(!state.newspaper||typeof state.newspaper!=='object')state.newspaper={articles:structuredClone(newspaperSeedArticles),pitches:[],classifieds:[],personals:[],bounties:[],comics:[],ads:[]};const n=state.newspaper;for(const key of ['articles','pitches','classifieds','personals','bounties','comics','ads'])if(!Array.isArray(n[key]))n[key]=[];if(!n.articles.length)n.articles=structuredClone(newspaperSeedArticles);return n}
let newspaperTab='front';
function submitReporterPitch(){const title=document.getElementById('pitchTitle')?.value.trim(),body=document.getElementById('pitchBody')?.value.trim();if(!title||body.length<20){toast('Add a title and at least 20 characters for the pitch.');return}const n=ensureNewspaperData();n.pitches.unshift({id:'pitch-'+Date.now(),title,body,author:state.name,authorId:state.playerId,createdAt:Date.now(),status:'Sent to sugarvalves [1963573]'});save();render();toast('Pitch sent to the Lead Reporter for review.')}
function submitClassified(){const title=document.getElementById('classifiedTitle')?.value.trim(),body=document.getElementById('classifiedBody')?.value.trim(),free=!!state.stockBenefits?.messaging||Number(state.stocks?.YAZOO||0)>=1000000;if(!title||!body){toast('Add a headline and message.');return}const fee=250000;if(!free&&!isOwner()&&state.cash<fee){toast(`Classified ads cost ${money(fee)}.`);return}if(!free&&!isOwner())state.cash-=fee;ensureNewspaperData().classifieds.unshift({id:'classified-'+Date.now(),title,body,author:state.name,createdAt:Date.now(),fee:free?0:fee});addActivity('📰','Classified ad placed',title);save();render();toast(free?'Classified ad placed free with your stock benefit.':`Classified ad placed for ${money(fee)}.`)}
function submitPersonal(){const body=document.getElementById('personalBody')?.value.trim();if(!body){toast('Write a personal ad first.');return}const fee=10000;if(!isOwner()&&state.cash<fee){toast(`Personals cost ${money(fee)}.`);return}if(!isOwner())state.cash-=fee;ensureNewspaperData().personals.unshift({id:'personal-'+Date.now(),body,author:state.name,createdAt:Date.now()});save();render();toast(`Personal ad placed for ${money(fee)}.`)}
function placeBounty(){const target=document.getElementById('bountyTarget')?.value.trim(),reward=Math.floor(Number(document.getElementById('bountyReward')?.value)||0),reason=document.getElementById('bountyReason')?.value.trim();if(!/^\d{7}$/.test(target)||String(target)===String(state.playerId)||reward<1000||!reason){toast('Enter a different 7-digit player ID, a reward of at least 1,000 cr, and a reason.');return}if(!isOwner()&&state.cash<reward){toast('You do not have enough credits for that bounty.');return}if(!isOwner())state.cash-=reward;ensureNewspaperData().bounties.unshift({id:'bounty-'+Date.now(),targetId:target,reward,reason,placedBy:state.name,placedById:state.playerId,createdAt:Date.now(),claimedBy:null});addActivity('⚖','Bounty placed',`[${target}] · ${money(reward)}`);save();render();toast(`Bounty placed on [${target}] for ${money(reward)}.`)}
function claimBounty(id){const bounty=ensureNewspaperData().bounties.find(x=>x.id===id);if(!bounty||bounty.claimedBy){toast('That bounty is no longer available.');return}if(String(bounty.targetId)===String(state.playerId)){toast('You cannot claim a bounty on yourself.');return}bounty.claimedBy=state.playerId;bounty.claimedByName=state.name;state.cash+=bounty.reward;state.attackWins=(state.attackWins||0)+1;addActivity('⚖','Bounty claimed',`+${money(bounty.reward)} · [${bounty.targetId}]`);save();render();toast(`Bounty claimed. +${money(bounty.reward)}.`)}
function submitComic(){if(Number(state.level||0)<10){toast('Comics unlock at level 10.');return}const title=document.getElementById('comicTitle')?.value.trim(),body=document.getElementById('comicBody')?.value.trim();if(!title||body.length<20){toast('Add a title and at least 20 characters.');return}ensureNewspaperData().comics.unshift({id:'comic-'+Date.now(),title,body,author:state.name,authorId:state.playerId,createdAt:Date.now(),status:'Submitted'});state.awards=[...(state.awards||[])].filter(x=>x!=='Comic Creator');state.awards.push('Comic Creator');state.merits=(state.merits||0)+1;save();render();toast('Comic submitted to the newspaper. If accepted, it earns an honor and 250 points.')}
function submitGraphicAd(){const title=document.getElementById('adTitle')?.value.trim(),body=document.getElementById('adBody')?.value.trim(),days=Math.max(7,Math.min(90,Math.floor(Number(document.getElementById('adDays')?.value)||7))),fee=500000*days,free=Number(state.stocks?.YAZOO||0)>=1000000||state.stockBenefits?.yazoo; if(!title||!body){toast('Add a banner title and message.');return}if(!free&&!isOwner()&&state.cash<fee){toast(`Graphic advertising requires ${money(fee)} on hand.`);return}if(!free&&!isOwner())state.cash-=fee;ensureNewspaperData().ads.unshift({id:'ad-'+Date.now(),title,body,days,fee:free?0:fee,author:state.name,createdAt:Date.now(),status:'Pending review'});save();render();toast(free?'Banner submitted with the Yazoo stock benefit.':`Banner submitted for ${days} days.`)}
function newspaperArticleCard(article){return `<article class="newspaper-article card"><div class="eyebrow">${newspaperEscape(article.author)} · ${newspaperEscape(article.date||new Date(article.createdAt||Date.now()).toLocaleDateString())}</div><h3>${newspaperEscape(article.title)}</h3><p>${newspaperEscape(article.body)}</p><button class="text-btn" data-newspaper-read="${article.id}">Read article →</button></article>`}
function newspaperPage(){const n=ensureNewspaperData(),tab=newspaperTab,tabButton=(id,label)=>`<button class="tag newspaper-tab ${tab===id?'green':''}" data-newspaper-tab="${id}">${label}</button>`,front=n.articles.slice(0,7);let content='';if(tab==='front')content=`<div class="newspaper-front"><section><div class="card newspaper-lead"><div class="eyebrow">THE GORE-WARS CITY TIMES · FRONT PAGE</div><h2>${newspaperEscape(front[0].title)}</h2><p>${newspaperEscape(front[0].body)}</p><span class="muted-note">By ${newspaperEscape(front[0].author)} · ${newspaperEscape(front[0].date)}</span></div><div class="newspaper-article-grid">${front.slice(1).map(newspaperArticleCard).join('')}</div></section><aside><div class="card"><div class="panel-title">Tell your story</div><p class="muted-note">Pitch an article to sugarvalves [1963573], the Lead Reporter.</p><input id="pitchTitle" class="name-input" maxlength="80" placeholder="Pitch title"><textarea id="pitchBody" class="name-input" rows="5" maxlength="1500" placeholder="What should the city know?"></textarea><button class="btn" id="submitPitch">Send pitch</button></div><div class="card"><div class="panel-title">Quick links</div><div class="list"><button class="btn secondary" data-view="jobs">Job listings</button><button class="btn secondary" data-view="properties">Properties</button><button class="btn secondary" data-view="hall">Hall of Fame</button></div></div></aside></div>`;else if(tab==='archive')content=`<div class="newspaper-article-grid">${n.articles.map(newspaperArticleCard).join('')}</div>`;else if(tab==='classifieds')content=`<div class="grid grid-2"><section><div class="card"><div class="panel-title">Place a classified ad</div><p class="muted-note">Listings cost ${money(250000)}. Messaging Inc stock benefits can make them free.</p><input id="classifiedTitle" class="name-input" maxlength="80" placeholder="Headline"><textarea id="classifiedBody" class="name-input" rows="5" maxlength="1000" placeholder="What are you selling, buying, or offering?"></textarea><button class="btn" id="submitClassified">Place ad</button></div></section><aside><div class="list">${n.classifieds.map(x=>`<div class="card newspaper-listing"><div class="eyebrow">${newspaperEscape(x.author)}</div><h3>${newspaperEscape(x.title)}</h3><p>${newspaperEscape(x.body)}</p><span class="muted-note">${new Date(x.createdAt).toLocaleString()}</span></div>`).join('')||'<div class="empty">No classified ads yet.</div>'}</div></aside></div>`;else if(tab==='personals')content=`<div class="grid grid-2"><section><div class="card"><div class="panel-title">Personals</div><p class="muted-note">Post a personal for ${money(10000)}. Keep it in character and respectful.</p><textarea id="personalBody" class="name-input" rows="5" maxlength="800" placeholder="Introduce yourself to Blackharbor..."></textarea><button class="btn" id="submitPersonal">Place personal</button></div></section><aside><div class="list">${n.personals.map(x=>`<div class="card newspaper-listing"><p>${newspaperEscape(x.body)}</p><span class="muted-note">${newspaperEscape(x.author)} · ${new Date(x.createdAt).toLocaleString()}</span></div>`).join('')||'<div class="empty">No personals yet.</div>'}</div></aside></div>`;else if(tab==='bounties')content=`<div class="grid grid-2"><section><div class="card"><div class="panel-title">Place a bounty</div><p class="muted-note">Fund a reward so another player can claim it after defeating the target.</p><input id="bountyTarget" class="name-input" maxlength="7" placeholder="Target player ID" inputmode="numeric"><input id="bountyReward" class="name-input" placeholder="Reward in credits" inputmode="numeric"><textarea id="bountyReason" class="name-input" rows="4" maxlength="500" placeholder="Reason for the bounty"></textarea><button class="btn" id="placeBounty">Place bounty</button></div></section><aside><div class="list">${n.bounties.filter(x=>!x.claimedBy).map(x=>`<div class="card newspaper-listing"><div class="resource"><strong>Target [${newspaperEscape(x.targetId)}]</strong><b>${money(x.reward)}</b></div><p>${newspaperEscape(x.reason)}</p><span class="muted-note">Placed by ${newspaperEscape(x.placedBy)}</span><button class="btn secondary claim-bounty" data-bounty-id="${x.id}">Claim after attack</button></div>`).join('')||'<div class="empty">No active bounties.</div>'}</div></aside></div>`;else if(tab==='comics')content=`<div class="grid grid-2"><section><div class="card"><div class="panel-title">Submit a comic</div><p class="muted-note">Comics unlock at level 10. Accepted comics earn an honor and 250 points.</p><input id="comicTitle" class="name-input" maxlength="80" placeholder="Comic title"><textarea id="comicBody" class="name-input" rows="6" maxlength="1500" placeholder="Comic script or caption"></textarea><button class="btn" id="submitComic" ${state.level<10?'disabled':''}>Submit comic</button></div></section><aside><div class="list">${n.comics.map(x=>`<div class="card newspaper-listing"><h3>${newspaperEscape(x.title)}</h3><p>${newspaperEscape(x.body)}</p><span class="muted-note">${newspaperEscape(x.author)} · ${x.status}</span></div>`).join('')||'<div class="empty">No comics submitted yet.</div>'}</div></aside></div>`;else if(tab==='chronicles')content=`<div class="card"><div class="panel-title">Chronicles</div><p class="muted-note">The Chronicle archives preserve the city’s turning points, faction wars, and major events.</p><div class="newspaper-article-grid">${n.articles.slice().reverse().map(newspaperArticleCard).join('')}</div></div>`;else content=`<div class="grid grid-2"><section><div class="card"><div class="panel-title">Graphic advertising</div><p class="muted-note">Banners cost ${money(500000)} per day for 7–90 days. Yazoo shareholders receive the placement free.</p><input id="adTitle" class="name-input" maxlength="80" placeholder="Banner title"><textarea id="adBody" class="name-input" rows="4" maxlength="800" placeholder="Banner message"></textarea><input id="adDays" class="name-input" value="7" inputmode="numeric" placeholder="Days (7–90)"><button class="btn" id="submitGraphicAd">Submit banner</button></div></section><aside><div class="list">${n.ads.map(x=>`<div class="card newspaper-listing"><h3>${newspaperEscape(x.title)}</h3><p>${newspaperEscape(x.body)}</p><span class="muted-note">${x.days} days · ${x.status} · ${x.fee?money(x.fee):'Yazoo benefit'}</span></div>`).join('')||'<div class="empty">No banners submitted yet.</div>'}</div></aside></div>`;return layout(`<div class="newspaper-masthead card"><div><div class="eyebrow">BLACKHARBOR // CITY DESK</div><h2>Gore-Wars City Times</h2><p>The official record of deals, danger, and city life.</p></div><div class="newspaper-tabs">${tabButton('front','Front page')}${tabButton('archive','Archive')}${tabButton('classifieds','Classifieds')}${tabButton('personals','Personals')}${tabButton('bounties','Bounties')}${tabButton('comics','Comics')}${tabButton('chronicles','Chronicles')}${tabButton('advertising','Advertising')}</div></div>${content}`, 'City Times // Newspaper', tab==='front'?'Today in Blackharbor':tab[0].toUpperCase()+tab.slice(1), 'Read the paper, place an ad, and leave your mark in the city record.');}
const itemCategories=['Equipment','Useful Supplies','Medical','Drugs','Energy Drinks','Alcohol','Candy','Other Boosters','Enhancers','Special','Tools','Materials','Supply Packs','General Shopping','Clothing','Jewelry','Flowers','Plushies','Cars','Artifacts','Collectibles','Miscellaneous'];
function itemCategory(item){if(item.category&&itemCategories.includes(item.category))return item.category;const n=(item.name||'').toLowerCase();if(item.type==='Weapon'||item.type==='Armor')return 'Equipment';if(item.type==='Tool'||/lockpick|computer|camera|skimmer/.test(n))return 'Tools';if(/drug|cannabis|ecstasy|ketamine|lsd|opium|pcp|shrooms|speed|vicodin|xanax/.test(n))return 'Drugs';if(/armor|plate|gun|sidearm|weapon|sword/.test(n))return 'Equipment';if(/shell|ammo|bandage|medical|wrap/.test(n))return 'Medical';if(/enhancer|glasses|razor|bike|mask|drive|tape|megaphone|lighter/.test(n))return 'Enhancers';if(/supply|parcel|case|kit/.test(n))return 'Supply Packs';if(/flower|jewel|plush|car|artifact|collectible/.test(n))return 'Collectibles';return 'Miscellaneous'}
function inventory(){if(state.travel?.status==='abroad')return layout('<div class=\"card empty\">Your main inventory is unavailable while abroad. Use your travel inventory or return to Blackharbor.</div>','Travel // Inventory restricted','Inventory unavailable','Carried items are managed through the travel inventory while abroad.');const items=state.inventory||[];return layout('<div class="card"><div class="section-head" style="margin-top:0"><h2>Items inventory</h2><p>'+items.length+' unique items · purchases saved automatically</p></div><p class="muted-note">Items can come from shops, crimes, city finds, the Dump, NPC loot, missions, or player trades. Select a category to browse what you carry.</p><div class="award-filters item-filters"><button class="tag item-filter green" data-item-category="All">All</button>'+itemCategories.map(c=>'<button class="tag item-filter" data-item-category="'+c+'">'+c+'</button>').join('')+'</div><div class="item-grid">'+(items.map((i,n)=>{const cat=itemCategory(i),uses=i.maxUses?((i.uses??i.maxUses)+' / '+i.maxUses):'Reusable',sell=Math.max(1,Math.floor((i.price||100)*.55));return '<div class="item" data-item-category="'+cat+'"><div class="item-icon"><img src="'+itemAsset(i.name)+'" alt="'+i.name+' render"></div><strong>'+i.name+'</strong><span>'+cat+' · Qty '+i.qty+'</span><div class="progress">Uses: '+uses+' · Sell: '+money(sell)+'</div><div class="item-actions"><button class="btn secondary item-use" data-index="'+n+'" '+(i.maxUses&&i.uses<=0?'disabled':'')+'>Use</button><button class="btn item-sell" data-index="'+n+'">Sell</button></div></div>'}).join('')||'<div class="empty">No items yet. Browse a shop to stock your inventory.</div>')+'</div></div><div class="section-head"><h2>Item sources</h2><p>Tradeable city economy</p></div><div class="card"><div class="list"><div class="list-row"><strong>Buy or sell</strong><span>Item Market · Auction House · East Side · player trades</span></div><div class="list-row"><strong>Find</strong><span>City finds · Dump · NPC loot · crimes · missions</span></div><div class="list-row"><strong>Legacy categories</strong><span>Virus, Electronics, Non-tradeable, and Books are not active categories.</span></div></div></div>', 'Character // Items', 'What you carry defines your exits.', 'Every item has a source, category, and use case.');}
