function missionDone(id){const items=state.inventory||[];const views=state.visitedViews||{};switch(id){case'job':return !!state.job?.sector;case'gym':return state.trained>0;case'gym2':return state.trained>1;case'crime':return state.crimes>0;case'crime3':return state.crimes>=3;case'city':return !!views.city;case'shops':return !!views.shops;case'inventory':return !!views.inventory;case'market':case'market2':return !!views.market;case'weapon':return items.some(i=>i.type==='Weapon'||/sidearm|gun|weapon/i.test(i.name));case'ammo':return items.some(i=>i.type==='Ammunition'||/ammo|shell/i.test(i.name));case'attack':return (state.attacks||0)>0;case'attackwin':return (state.attackWins||0)>0;case'cash250':return state.cash>=250;case'heat2':return state.heat>=2;case'hospital':return !!views.hospital;case'bank':return !!views.market;case'factions':return !!views.factions;case'power12':return state.power>=12;case'resilience12':return state.resilience>=12;case'stat15':return Math.max(state.power,state.resilience,state.reflexes,state.precision)>=15;case'hall':return !!views.hall;case'missions':return !!views.missions;case'armor':return items.some(i=>i.type==='Armor'||/armor/i.test(i.name));case'award':return (state.awards||[]).length>0;case'level2':return state.level>=2;default:return false}}
function missions(){const active=Math.min(state.completedMissions||0,starterMissions.length-1);return layout(`<div class="grid grid-2"><section><div class="card"><div class="eyebrow">NEW PLAYER GUIDE // ${active+1} OF ${starterMissions.length}</div><h2>${starterMissions[active].title}</h2><p class="muted-note">${starterMissions[active].desc}</p><div class="list">${starterMissions[active].goals.map(g=>`<div class="list-row"><div><strong>${g[0]}</strong><span>${missionDone(g[1])?'Objective complete':'Still to do'}</span></div><span class="tag ${missionDone(g[1])?'green':''}">${missionDone(g[1])?'✓':'Open'}</span></div>`).join('')}</div>${starterMissions[active].goals.every(g=>missionDone(g[1]))?'<button class="btn" id="claimMission" style="margin-top:15px">Claim '+money(starterMissions[active].reward)+' + XP</button>':'<p class="muted-note" style="margin-top:15px">Complete every objective to unlock the reward.</p>'}</div></section><aside><div class="card"><div class="label">Mission track</div><div class="metric">${state.completedMissions||0} / ${starterMissions.length}</div><div class="meter"><i style="width:${(state.completedMissions||0)/starterMissions.length*100}%"></i></div><p class="muted-note">Missions guide your first days in Blackharbor. Rewards are saved when claimed.</p></div><div class="list">${starterMissions.map((m,i)=>`<div class="list-row"><div><strong>${i+1}. ${m.title}</strong><span>${i<(state.completedMissions||0)?'Completed':i===active?'Current':'Locked'}</span></div><span class="tag ${i<(state.completedMissions||0)?'green':''}">${i<(state.completedMissions||0)?'✓':i===active?'Live':'Locked'}</span></div>`).join('')}</div></aside></div>`, 'Progression // New Player Missions', 'Start your journey.', 'A guided route through the gym, jobs, shops, city, combat, and faction life.');}
