 ['Alcoholics Synonymous','ASS',1000000,'Active','7 days','1x Six Pack of Alcohol',280],['Big Al’s Gun Shop','BAG',3000000,'Active','7 days','1x Ammunition Pack',450],['Crude & Co','CNC',7500000,'Active','31 days','80,000,000 cr',1200],['Empty Lunchbox Traders','ELT',5000000,'Passive','—','10% Home Upgrade Discount',700],['Evil Ducks Candy Corp','EVL',100000,'Active','7 days','1,000 Happy',90],['Feathery Hotels Group','FHG',2000000,'Active','7 days','1x Feathery Hotel Coupon',800],['Grain','GRN',500000,'Active','31 days','4,000,000 cr',340],['Herbal Releaf Co.','CBD',350000,'Active','7 days','50 Nerve',500],['Home Retail Group','HRG',10000000,'Active','31 days','1x Random Property',1400],['I Industries Ltd.','IIL',1000000,'Passive','—','50% Virus Coding Time Reduction',1000],['Insured On Us','IOU',3000000,'Active','31 days','12,000,000 cr',850],['International School TC','IST',100000,'Passive','—','Free Education Courses',600],['Legal Authorities Group','LAG',750000,'Active','7 days','1x Lawyer Business Card',400],['Lo Squalo Waste Management','LOS',7500000,'Passive','—','25% Mission income boost',1100],['Lucky Shots Casino','LSC',500000,'Active','7 days','1x Lottery Voucher',250],['Mc Smoogle Corp.','MCS',350000,'Active','7 days','100 Energy',900],['Messaging Inc.','MSG',300000,'Passive','—','Free Classified Advertising',300],['Munster Beverage Corp.','MUN',5000000,'Active','7 days','1x Six Pack of Energy Drink',750],['Performance Ribaldry Network','PRN',1000000,'Active','7 days','1x Erotic DVD',390],['PointLess','PTS',10000000,'Active','7 days','100 Points',1500],['Symbiotic Ltd.','SYM',500000,'Active','7 days','1x Drug Pack',450],['Syscore MFG','SYS',3000000,'Passive','—','Advanced Firewall',700],['TC Media Productions','TCP',1000000,'Passive','—','Company Sales Boost',500],['TC Music Industries','TMI',6000000,'Active','31 days','25,000,000 cr',1300],['Tell Group Plc.','TGP',2500000,'Passive','—','Company Advertising Boost',900],['The Gore-Wars City Times','TCT',100000,'Active','31 days','1,000,000 cr',200],['Gore-Wars & Shanghai Banking','TSB',3000000,'Active','31 days','50,000,000 cr',1000],['Gore-Wars City Clothing','TCC',7500000,'Active','31 days','1x Clothing Cache',950],['Gore-Wars City Health Service','THS',150000,'Active','7 days','1x Box of Medical Supplies',350],['Gore-Wars City Investments','TCI',1500000,'Passive','—','10% Bank Interest Bonus',850],['Gore-Wars City Motors','TCM',1000000,'Passive','—','10% Racing Skill Boost',760],['West Side University','WSU',1000000,'Passive','—','10% Education Course Time Reduction',580],['Wind Lines Travel','WLT',9000000,'Passive','—','Private Jet Access',1250],['Yazoo','YAZ',1000000,'Passive','—','Free Banner Advertising',280]
