function forumBoardById(id){return forumBoardCatalog.find(x=>x.id===id)||forumBoardCatalog.find(x=>x.id==='general')}
function forumBoardAccess(board){if(!board)return false;if(isOwner()||board.access==='public')return true;if(board.access==='faction')return !!state.faction;if(board.access==='company')return !!state.company;if(board.access==='donator')return Number(state.donator?.days)>0;if(board.access==='vip')return Number(state.karma||0)>=1000;if(board.access==='christmas')return !!state.christmasTown;if(board.access==='wiki')return !!state.wikiContributor;if(board.access==='reporter')return !!state.reporter;if(board.access==='elimination')return !!state.elimination;return false}
function forumCanPost(board){return !!board&&forumBoardAccess(board)&&(board.postable==='member'||board.postable==='admin'&&isOwner())}
function forumEnsureData(){if(!state.forum||typeof state.forum!=='object')state.forum={threads:[],nextThreadId:1,nextPostId:1,ratings:{},reports:[],karmaByPlayer:{}};const f=state.forum;if(!Array.isArray(f.threads))f.threads=[];if(!Number.isFinite(f.nextThreadId))f.nextThreadId=f.threads.length+1;if(!Number.isFinite(f.nextPostId))f.nextPostId=1;if(!f.ratings||typeof f.ratings!=='object')f.ratings={};if(!Array.isArray(f.reports))f.reports=[];if(!f.karmaByPlayer||typeof f.karmaByPlayer!=='object')f.karmaByPlayer={};if(!Number.isFinite(state.karma)||state.karma<0)state.karma=0;if(!f.threads.length){const now=Date.now();f.threads=[{id:'t'+f.nextThreadId++,boardId:'announcements',title:'Welcome to the Gore-Wars forums',authorId:'1000001',authorName:'Gore-Wars Staff',createdAt:now-86400000,updatedAt:now-86400000,lastReplyAt:null,locked:true,graveyard:false,views:0,posts:[{id:'p'+f.nextPostId++,authorId:'1000001',authorName:'Gore-Wars Staff',body:'Welcome to the official Gore-Wars forums. Read the social guidelines before posting, keep discussions useful, and report violations through the Reports page.',format:'text',mediaUrl:'',createdAt:now-86400000,editedAt:null,karma:0,ratings:{}}]},{id:'t'+f.nextThreadId++,boardId:'general',title:'Welcome to Blackharbor discussion',authorId:'1000001',authorName:'Gore-Wars Staff',createdAt:now-3600000,updatedAt:now-3600000,lastReplyAt:null,locked:false,graveyard:false,views:0,posts:[{id:'p'+f.nextPostId++,authorId:'1000001',authorName:'Gore-Wars Staff',body:'Introduce yourself, share your first city goal, and help new players find their way around Blackharbor.',format:'text',mediaUrl:'',createdAt:now-3600000,editedAt:null,karma:0,ratings:{}}]}]};return f}
function forumThreadById(id){return forumEnsureData().threads.find(x=>String(x.id)===String(id))}
function forumPostById(id){for(const thread of forumEnsureData().threads){const post=thread.posts?.find(x=>String(x.id)===String(id));if(post)return {thread,post}}return null}
function forumEscape(value){return String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function forumSafeUrl(value){const url=String(value||'').trim();return /^https?:\/\//i.test(url)?forumEscape(url):''}
function forumRelativeTime(at){const seconds=Math.max(0,Math.floor((Date.now()-Number(at||Date.now()))/1000));if(seconds<60)return 'just now';if(seconds<3600)return Math.floor(seconds/60)+'m ago';if(seconds<86400)return Math.floor(seconds/3600)+'h ago';return Math.floor(seconds/86400)+'d ago'}
function forumPostBody(post){const body=String(post.body||'');let html=post.format==='table'?'<table class="forum-table"><tbody>'+body.split(/\r?\n/).slice(0,20).map(row=>'<tr>'+row.split('|').slice(0,12).map(cell=>'<td>'+forumEscape(cell.trim())+'</td>').join('')+'</tr>').join('')+'</tbody></table>':forumEscape(body).replace(/\r?\n/g,'<br>');const url=forumSafeUrl(post.mediaUrl);if(url&&post.format==='image')html+='<div class="forum-media"><img src="'+url+'" alt="Hosted forum image" loading="lazy"></div>';if(url&&post.format==='video')html+='<div class="forum-media"><video controls preload="metadata" src="'+url+'">Hosted video</video></div>';return html||'<span class="muted-note">Empty post</span>'}
function forumSearchMatch(text,query){const hay=String(text||'').toLowerCase();const exact=[...String(query).matchAll(/"([^"]+)"/g)].map(x=>x[1].toLowerCase());if(exact.some(x=>!hay.includes(x)))return false;const by=String(query).match(/(?:^|\s)by:([^\s]+)/i);if(by){const author=String(text).toLowerCase();if(!author.includes(by[1].toLowerCase()))return false}const alternatives=String(query).split('|').map(x=>x.trim()).filter(Boolean);const matchesClause=clause=>{const tokens=clause.replace(/"[^"]+"/g,' ').replace(/[()]/g,' ').match(/[+-]?\S+/g)||[];for(let token of tokens){if(/^by:/i.test(token)||token.length<2)continue;const required=token[0]==='+';const excluded=token[0]==='-';if(required||excluded)token=token.slice(1);if(!token||['as','at','be','by','de','in','is','it','of','on','or','to'].includes(token.toLowerCase()))continue;const wildcard=token.endsWith('*'),term=(wildcard?token.slice(0,-1):token).toLowerCase();const found=wildcard?hay.split(/\s+/).some(word=>word.startsWith(term)):hay.includes(term);if(excluded&&found)return false;if(required&&!found)return false;if(!required&&!excluded&&!found)return false}return true};return alternatives.length>1?alternatives.some(matchesClause):matchesClause(String(query))}
function forumSearchResults(query){if(String(query||'').trim().length<2)return [];const results=[];for(const thread of forumEnsureData().threads){const board=forumBoardById(thread.boardId);if(!forumBoardAccess(board))continue;for(const post of thread.posts||[]){const text=thread.title+' '+board.name+' '+post.authorName+' '+post.authorId+' '+post.body;if(forumSearchMatch(text,query))results.push({thread,post,board})}}return results.sort((a,b)=>Number(b.post.createdAt)-Number(a.post.createdAt))}
