function forumCompose(kind,thread){const board=forumBoardById(forumBoard);if(kind==='thread'&&!forumCanPost(board))return '<div class="empty">Posting is unavailable in this forum. Announcements and Community Events are staff-managed.</div>';if(kind==='reply'&&(!thread||thread.locked||thread.graveyard||!forumBoardAccess(board)))return '<div class="empty">This thread is locked or unavailable for replies.</div>';const prefix=kind==='thread'?'forumNew':'forumReply';return '<div class="card forum-compose"><div class="panel-title">'+(kind==='thread'?'Start a thread':'Reply to thread')+'</div>'+(kind==='thread'?'<input id="forumNewTitle" class="name-input" maxlength="120" placeholder="Thread title">':'')+'<textarea id="'+prefix+'Body" class="name-input" rows="7" maxlength="8000" placeholder="Write your post. Text, tables, hosted images, and hosted videos are supported."></textarea><div class="form-row"><select id="'+prefix+'Format" class="name-input"><option value="text">Text</option><option value="table">Table (separate cells with |)</option><option value="image">Hosted image</option><option value="video">Hosted video</option></select><input id="'+prefix+'Media" class="name-input" placeholder="Optional https:// hosted media URL"><button class="btn" data-forum-submit="'+kind+'">'+(kind==='thread'?'Post thread':'Post reply')+'</button></div><small class="muted-note">Posts under 30 characters do not affect karma.</small></div>'}
function forumCreateThread(){const f=forumEnsureData(),board=forumBoardById(forumBoard),title=document.getElementById('forumNewTitle')?.value.trim(),body=document.getElementById('forumNewBody')?.value.trim(),format=document.getElementById('forumNewFormat')?.value||'text',media=document.getElementById('forumNewMedia')?.value.trim()||'';if(!forumCanPost(board)){toast('You cannot create threads in this forum.');return}if(!title||title.length<3||!body){toast('Add a title and post body.');return}if(['image','video'].includes(format)&&!forumSafeUrl(media)){toast('Hosted media must use an http or https URL.');return}const now=Date.now(),thread={id:'t'+f.nextThreadId++,boardId:board.id,title,authorId:String(state.playerId),authorName:state.name,createdAt:now,updatedAt:now,lastReplyAt:null,locked:false,graveyard:false,views:0,posts:[{id:'p'+f.nextPostId++,authorId:String(state.playerId),authorName:state.name,body,format,mediaUrl:media,createdAt:now,editedAt:null,karma:0,ratings:{}}]};f.threads.unshift(thread);forumThreadId=thread.id;addActivity('▤','Forum thread posted',board.name+' · '+title);save();render();toast('Thread posted.')}
