function forumRatePost(id,value){const found=forumPostById(id);if(!found)return;const {thread,post}=found,board=forumBoardById(thread.boardId),v=Number(value),rater=String(state.playerId),existing=post.ratings?.[rater],karmaExcluded=['my-faction','my-company','elimination'].includes(board.id);if(String(post.authorId)===rater||String(post.body||'').trim().length<30||thread.locked||thread.graveyard||karmaExcluded||Number(state.accountCreatedAt||Date.now())>Date.now()-86400000){toast('This post is not eligible for karma rating.');return}if(![-1,1].includes(v))return;if(existing&&Date.now()-Number(existing.at||0)>15*60*1000){toast('The rating change window has closed.');return}post.ratings=post.ratings||{};post.karma=Number(post.karma)||0;const delta=existing? v-existing.value:v;post.karma+=delta;const authorId=String(post.authorId);forumEnsureData().karmaByPlayer[authorId]=Math.max(0,(Number(forumEnsureData().karmaByPlayer[authorId])||0)+delta);if(authorId===rater)state.karma=Math.max(0,(Number(state.karma)||0)+delta);post.ratings[rater]={value:v,at:Date.now()};save();render();toast(v===1?'Upvote recorded.':'Downvote recorded.')}
